"""Repository for dq_recommendations -- actionable fixes generated by dqBot."""

import json
import logging

from backend.db.connection import get_conn

logger = logging.getLogger(__name__)

_VALID_STATUSES = frozenset({"approved", "rejected", "snoozed", "superseded", "dismissed"})


def create_recommendation(
    user_id: int,
    run_id: int,
    observation_id: int,
    action_type: str,
    headline: str,
    rationale: str,
    self_classification: str,
    rank_in_run: int,
    affected_entity_type: str,
    affected_entity_ids: list[str],
    outlier_signals: dict | None = None,
    action_payload: dict | None = None,
) -> dict:
    """Insert a recommendation into dq_recommendations.

    affected_entity_ids, outlier_signals, and action_payload are marshaled to
    JSONB via json.dumps. action_payload (migration 042) carries the
    machine-actionable instructions for the approve-applies path (spec S4);
    None for action_types that stay record-only, or when a pre-detector /
    the LLM pass couldn't derive one.
    Returns the inserted row as dict.
    """
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO dq_recommendations
                (user_id, run_id, observation_id, action_type, headline, rationale,
                 self_classification, rank_in_run, affected_entity_type, affected_entity_ids,
                 outlier_signals, action_payload)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING id, user_id, run_id, observation_id, action_type, headline,
                      rationale, self_classification, rank_in_run, affected_entity_type,
                      affected_entity_ids, status, user_note, reviewed_at,
                      superseded_by, created_at, promoted_at, outlier_signals,
                      action_payload, applied_at, applied_detail
            """,
            (
                user_id,
                run_id,
                observation_id,
                action_type,
                headline,
                rationale,
                self_classification,
                rank_in_run,
                affected_entity_type,
                json.dumps(affected_entity_ids),
                json.dumps(outlier_signals) if outlier_signals is not None else None,
                json.dumps(action_payload) if action_payload is not None else None,
            ),
        )
        r = cur.fetchone()

    return {
        "id": r[0],
        "user_id": r[1],
        "run_id": r[2],
        "observation_id": r[3],
        "action_type": r[4],
        "headline": r[5],
        "rationale": r[6],
        "self_classification": r[7],
        "rank_in_run": r[8],
        "affected_entity_type": r[9],
        "affected_entity_ids": r[10],
        "status": r[11],
        "user_note": r[12],
        "reviewed_at": r[13],
        "superseded_by": r[14],
        "created_at": r[15],
        "promoted_at": r[16],
        "outlier_signals": r[17],
        "action_payload": r[18],
        "applied_at": r[19],
        "applied_detail": r[20],
    }


def list_for_observation(user_id: int, observation_id: int) -> list[dict]:
    """List all recommendations linked to one observation (any status).

    Used by the Receipt pane to render Layer 4 (Alternatives) -- sibling
    recommendations for the same finding, including superseded ones so the
    user can see the full history.
    """
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, user_id, run_id, observation_id, action_type, headline,
                   rationale, self_classification, rank_in_run,
                   affected_entity_type, affected_entity_ids, status, user_note,
                   reviewed_at, superseded_by, created_at, promoted_at,
                   outlier_signals, action_payload, applied_at, applied_detail
            FROM dq_recommendations
            WHERE user_id = %s AND observation_id = %s
            ORDER BY created_at DESC
            """,
            (user_id, observation_id),
        )
        rows = cur.fetchall()
    return [
        {
            "id": r[0],
            "user_id": r[1],
            "run_id": r[2],
            "observation_id": r[3],
            "action_type": r[4],
            "headline": r[5],
            "rationale": r[6],
            "self_classification": r[7],
            "rank_in_run": r[8],
            "affected_entity_type": r[9],
            "affected_entity_ids": r[10],
            "status": r[11],
            "user_note": r[12],
            "reviewed_at": r[13].isoformat() if r[13] else None,
            "superseded_by": r[14],
            "created_at": r[15].isoformat() if r[15] else None,
            "promoted_at": r[16].isoformat() if r[16] else None,
            "outlier_signals": r[17],
            "action_payload": r[18],
            "applied_at": r[19].isoformat() if r[19] else None,
            "applied_detail": r[20],
        }
        for r in rows
    ]


def list_pending(
    user_id: int,
    limit: int = 5,
    include_superseded: bool = False,
) -> list[dict]:
    """List recommendations for a user, ordered by promoted_at then rank_in_run.

    Promoted recs surface first (promoted_at DESC NULLS LAST), then un-promoted
    recs in rank order. This means a promoted rank-8 rec will appear before an
    un-promoted rank-1 rec in the result set.

    By default returns only status='pending' rows. When include_superseded=True,
    also returns status='superseded' rows so the all-findings expander can render
    the supersession chain (greyed cards with "replaced by ->" links).
    """
    statuses: list[str] = ["pending"]
    if include_superseded:
        statuses.append("superseded")
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, user_id, run_id, observation_id, action_type, headline,
                   rationale, self_classification, rank_in_run, affected_entity_type,
                   affected_entity_ids, status, user_note, reviewed_at,
                   superseded_by, created_at, promoted_at, outlier_signals,
                   action_payload, applied_at, applied_detail
            FROM dq_recommendations
            WHERE user_id = %s AND status = ANY(%s)
            ORDER BY promoted_at DESC NULLS LAST, rank_in_run ASC
            LIMIT %s
            """,
            (user_id, statuses, limit),
        )
        return [
            {
                "id": r[0],
                "user_id": r[1],
                "run_id": r[2],
                "observation_id": r[3],
                "action_type": r[4],
                "headline": r[5],
                "rationale": r[6],
                "self_classification": r[7],
                "rank_in_run": r[8],
                "affected_entity_type": r[9],
                "affected_entity_ids": r[10],
                "status": r[11],
                "user_note": r[12],
                "reviewed_at": r[13],
                "superseded_by": r[14],
                "created_at": r[15],
                "promoted_at": r[16],
                "outlier_signals": r[17],
                "action_payload": r[18],
                "applied_at": r[19],
                "applied_detail": r[20],
            }
            for r in cur.fetchall()
        ]


