def update_status(
    rec_id: int,
    new_status: str,
    user_note: str | None = None,
) -> dict | None:
    """Update the status of a recommendation.

    Validates new_status is in _VALID_STATUSES before executing.
    Sets reviewed_at = NOW().
    Returns the updated row as dict.
    """
    if new_status not in _VALID_STATUSES:
        raise ValueError(f"invalid status: {new_status}")

    with get_conn() as conn, conn.cursor() as cur:
        cur.execute(
            """
            UPDATE dq_recommendations
            SET status = %s, reviewed_at = NOW(), user_note = %s
            WHERE id = %s
            RETURNING id, user_id, run_id, observation_id, action_type, headline,
                      rationale, self_classification, rank_in_run, affected_entity_type,
                      affected_entity_ids, status, user_note, reviewed_at,
                      superseded_by, created_at, promoted_at, outlier_signals,
                      action_payload, applied_at, applied_detail
            """,
            (new_status, user_note, rec_id),
        )
        r = cur.fetchone()

    if r is None:
        return None
    return {
        "id": r[0],
        "user_id": r[1],
        "run_id": r[2],
        "observation_id": r[3],
        "action_type": r[4],
        "headline": r[5],
        "rationale": r[6],
        "self_classification": r[7],
        "rank_in_run": r[8],
        "affected_entity_type": r[9],
        "affected_entity_ids": r[10],
        "status": r[11],
        "user_note": r[12],
        "reviewed_at": r[13],
        "superseded_by": r[14],
        "created_at": r[15],
        "promoted_at": r[16],
        "outlier_signals": r[17],
        "action_payload": r[18],
        "applied_at": r[19],
        "applied_detail": r[20],
    }


def mark_applied(rec_id: int, detail: dict) -> dict | None:
    """Record what the approve-applies path (spec S5) actually did.

    Sets applied_at = NOW() and applied_detail = detail (JSONB). Called
    regardless of whether the apply succeeded -- detail carries either the
    applied action's summary or {"error": ...} / a record-only explanation;
    status still flips to approved via update_status separately (the verdict
    stands even when the apply needs a retry). Returns the updated row, or
    None if rec_id doesn't exist.
    """
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute(
            """
            UPDATE dq_recommendations
            SET applied_at = NOW(), applied_detail = %s
            WHERE id = %s
            RETURNING id, user_id, run_id, observation_id, action_type, headline,
                      rationale, self_classification, rank_in_run, affected_entity_type,
                      affected_entity_ids, status, user_note, reviewed_at,
                      superseded_by, created_at, promoted_at, outlier_signals,
                      action_payload, applied_at, applied_detail
            """,
            (json.dumps(detail), rec_id),
        )
        r = cur.fetchone()

    if r is None:
        return None
    return {
        "id": r[0],
        "user_id": r[1],
        "run_id": r[2],
        "observation_id": r[3],
        "action_type": r[4],
        "headline": r[5],
        "rationale": r[6],
        "self_classification": r[7],
        "rank_in_run": r[8],
        "affected_entity_type": r[9],
        "affected_entity_ids": r[10],
        "status": r[11],
        "user_note": r[12],
        "reviewed_at": r[13],
        "superseded_by": r[14],
        "created_at": r[15],
        "promoted_at": r[16],
        "outlier_signals": r[17],
        "action_payload": r[18],
        "applied_at": r[19],
        "applied_detail": r[20],
    }


def resolve_stale_cluster_recs(user_id: int, live_stable_ids: list[str]) -> int:
    """Auto-expire pending cluster-entity recs whose target dissolved in a
    recluster (spec S3): dismiss any pending recommendation linked to a
    cluster-entity observation whose entity_id (a stable_id) is not in
    live_stable_ids, the carried set from the new generation.

    Guard: an empty live_stable_ids means identity carry-forward was off or
    broken this run, NOT that every cluster dissolved -- in that case this
    is a no-op (returns 0) rather than mass-dismissing the queue.

    Returns the number of recommendations dismissed.
    """
    if not live_stable_ids:
        return 0

    with get_conn() as conn, conn.cursor() as cur:
        cur.execute(
            """
            UPDATE dq_recommendations r
            SET status = 'dismissed',
                reviewed_at = NOW(),
                user_note = '[auto] target cluster dissolved in recluster (stable_id no longer carried)'
            WHERE r.user_id = %s
              AND r.status = 'pending'
              AND r.affected_entity_type = 'cluster'
              AND EXISTS (
                  SELECT 1 FROM dq_observations o
                  WHERE o.id = r.observation_id
                    AND o.entity_type = 'cluster'
                    AND o.entity_id != ALL(%s)
              )
            """,
            (user_id, live_stable_ids),
        )
        return cur.rowcount


def supersede(old_rec_id: int, new_payload: dict) -> dict:
    """Supersede an old recommendation with a new one.

    Atomically:
      1. INSERT the new recommendation from new_payload
      2. UPDATE old rec: status='superseded', superseded_by=<new_id>

    new_payload may include an optional "action_payload" key (migration 042);
    absent/None is stored as NULL, same as create_recommendation.

    Returns the NEW recommendation as dict.
    """
    with get_conn() as conn, conn.cursor() as cur:
        # Insert the new recommendation
        cur.execute(
            """
            INSERT INTO dq_recommendations
                (user_id, run_id, observation_id, action_type, headline, rationale,
                 self_classification, rank_in_run, affected_entity_type, affected_entity_ids,
                 outlier_signals, action_payload)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING id, user_id, run_id, observation_id, action_type, headline,
                      rationale, self_classification, rank_in_run, affected_entity_type,
                      affected_entity_ids, status, user_note, reviewed_at,
                      superseded_by, created_at, promoted_at, outlier_signals,
                      action_payload, applied_at, applied_detail
            """,
            (
                new_payload["user_id"],
                new_payload["run_id"],
                new_payload["observation_id"],
                new_payload["action_type"],
                new_payload["headline"],
                new_payload["rationale"],
                new_payload["self_classification"],
                new_payload["rank_in_run"],
                new_payload["affected_entity_type"],
                json.dumps(new_payload["affected_entity_ids"]),
                json.dumps(new_payload["outlier_signals"]) if new_payload.get("outlier_signals") is not None else None,
                json.dumps(new_payload["action_payload"]) if new_payload.get("action_payload") is not None else None,
            ),
        )
        new_row = cur.fetchone()
        new_id = new_row[0]

        # Mark the old recommendation as superseded
        cur.execute(
            """
            UPDATE dq_recommendations
            SET status = 'superseded', superseded_by = %s
            WHERE id = %s
            """,
            (new_id, old_rec_id),
        )

    return {
        "id": new_row[0],
        "user_id": new_row[1],
        "run_id": new_row[2],
        "observation_id": new_row[3],
        "action_type": new_row[4],
        "headline": new_row[5],
        "rationale": new_row[6],
        "self_classification": new_row[7],
        "rank_in_run": new_row[8],
        "affected_entity_type": new_row[9],
        "affected_entity_ids": new_row[10],
        "status": new_row[11],
        "user_note": new_row[12],
        "reviewed_at": new_row[13],
        "superseded_by": new_row[14],
        "created_at": new_row[15],
        "promoted_at": new_row[16],
        "outlier_signals": new_row[17],
        "action_payload": new_row[18],
        "applied_at": new_row[19],
        "applied_detail": new_row[20],
    }


