def calibration_by_action_type(user_id: int, limit: int = 20) -> list[dict]:
    """Approval-rate rollup over the user's last-N recs, grouped by action_type.

    Only counts recs that have been reviewed (approved OR rejected). Snoozed,
    superseded, and dismissed are excluded because they're neither accept
    nor reject signals.

    Returns a list of dicts, one per action_type seen in the window:
      {
        "action_type": str,
        "approved": int,
        "rejected": int,
        "total_reviewed": int,
        "approval_rate": float,  # approved / total_reviewed, 0.0 if 0
      }
    Sorted by total_reviewed DESC so the most-reviewed types come first.
    """
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, action_type, status
            FROM dq_recommendations
            WHERE user_id = %s AND status IN ('approved', 'rejected')
            ORDER BY reviewed_at DESC
            LIMIT %s
            """,
            (user_id, limit),
        )
        rows = cur.fetchall()

    # Aggregate in Python by action_type
    counts: dict[str, dict] = {}
    for _id, action_type, status in rows:
        if action_type not in counts:
            counts[action_type] = {"approved": 0, "rejected": 0}
        counts[action_type][status] += 1

    result = []
    for action_type, c in counts.items():
        approved = c["approved"]
        rejected = c["rejected"]
        total_reviewed = approved + rejected
        approval_rate = approved / total_reviewed if total_reviewed > 0 else 0.0
        result.append(
            {
                "action_type": action_type,
                "approved": approved,
                "rejected": rejected,
                "total_reviewed": total_reviewed,
                "approval_rate": approval_rate,
            }
        )

    result.sort(key=lambda x: x["total_reviewed"], reverse=True)
    return result


def calibration_summary(user_id: int) -> dict:
    """Get calibration summary (approval rate, etc.) for a user.

    Counts recommendations by status over the user's history.
    Computes approval_rate = approved / (approved + rejected), with guard for zero.

    Returns dict with: approved, rejected, superseded, snoozed, dismissed, total, approval_rate
    """
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                COUNT(*) FILTER (WHERE status = 'approved') AS approved,
                COUNT(*) FILTER (WHERE status = 'rejected') AS rejected,
                COUNT(*) FILTER (WHERE status = 'superseded') AS superseded,
                COUNT(*) FILTER (WHERE status = 'snoozed') AS snoozed,
                COUNT(*) FILTER (WHERE status = 'dismissed') AS dismissed,
                COUNT(*) AS total
            FROM dq_recommendations
            WHERE user_id = %s
            """,
            (user_id,),
        )
        r = cur.fetchone()

    approved = r[0]
    rejected = r[1]
    superseded = r[2]
    snoozed = r[3]
    dismissed = r[4]
    total = r[5]

    # Compute approval_rate with guard for zero-denominator
    reviewed_count = approved + rejected
    approval_rate = approved / reviewed_count if reviewed_count > 0 else 0.0

    return {
        "approved": approved,
        "rejected": rejected,
        "superseded": superseded,
        "snoozed": snoozed,
        "dismissed": dismissed,
        "total": total,
        "approval_rate": approval_rate,
    }
